import fs from 'node:fs';import path from 'node:path';import vm from 'node:vm';import assert from 'node:assert/strict';
const shell=vm.runInNewContext(fs.readFileSync('sw.js','utf8').match(/const SHELL=(\[.*?\]);/s)[1]),cached=new Set(Array.from(shell,p=>new URL(p,'https://local/').pathname));let assets=0;
// New workspace features are delivered through the authenticated preview. They
// deliberately stay outside the service-worker shell; offline study uses a
