const explicitPackageOnly=/^\/(?:workspace-core-20261030\.js|i18n-20261030\.js|students\/(?:analysis-(?:core|adapter)|study-next-tools|next-tools|next-learning-core|handover(?:-ui)?)-20261030\.(?:js|css))$/;
for(const file of fs.readdirSync('students').filter(f=>f.endsWith('.html'))){const html=fs.readFileSync('students/'+file,'utf8');for(const match of html.matchAll(/(?:src|href)="([^"#]+\.(?:js|css)(?:\?[^"#]*)?)"/g)){if(/^https?:/.test(match[1]))continue;const local=new URL(match[1],'https://local/students/'+file).pathname;assert.ok(fs.existsSync('.'+local),file+' missing '+local);assert.ok(cached.has(local)||explicitPackageOnly.test(local),file+' has an unaccounted offline dependency '+local);if(explicitPackageOnly.test(local))assert.ok(!cached.has(local),'Private workspace source must not enter the shell cache: '+local);assets++;}}
console.log(JSON.stringify({status:'PASS',linkedAssetsChecked:assets,scope:'All linked assets exist. Legacy shell dependencies remain complete; new private workspace dependencies use explicit packages instead of authenticated source caching.'}));
